			row[OrgAddressSchema.Constants.OA_PostCode                      ] = "";
			row[OrgAddressSchema.Constants.OA_RL_NKRelatedPortCode          ] = "";
			row[OrgAddressSchema.Constants.OA_RN_NKCountryCode              ] = "";
			row[OrgAddressSchema.Constants.OA_State                         ] = "";
			row[OrgAddressSchema.Constants.OA_SuppressAddressValidationError] = false;
			row[OrgAddressSchema.Constants.OA_SystemCreateTimeUtc           ] = DBNull.Value;
			row[OrgAddressSchema.Constants.OA_SystemCreateUser              ] = "";
			row[OrgAddressSchema.Constants.OA_SystemLastEditTimeUtc         ] = DBNull.Value;
			row[OrgAddressSchema.Constants.OA_SystemLastEditUser            ] = "";
			row[OrgAddressSchema.Constants.OA_UseCumulativeFreeWaitingTime  ] = false;
			row[OrgAddressSchema.Constants.OA_ValidationStatus              ] = "NYV";
			row[OrgAddressSchema.Constants.OA_VerifiesContainerGrossWeight  ] = false;
		}

